window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-6e61465e0f300c90"]={"versions": [{"id": "FIG-6e61465e0f300c90", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Code- und Schema-Gegenüberstellungsdiagramm im Kontext der AUTOSAR XML-Persistenzregeln (<code>AUTOSAR_TR_XMLPersistenceRules</code>). Das Diagramm illustriert die Transformation von AUTOSAR-Modellstrukturen in W3C-XML-Schema-Definitionen (<code>xsd:choice</code>, <code>xsd:group</code>) und die entsprechende serielle Repräsentation in AUTOSAR-XML-Instanzdokumenten (ARXML).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Darstellung gliedert sich in zwei Zeilen:</p>\n<ul class=\"fig-list\"><li><strong>XML schema example</strong>: Enthält zwei aufeinanderfolgende XML-Schema-Ausdrücke:\n<ol class=\"fig-list\"><li><code>&lt;xsd:choice minOccurs=&quot;0&quot; maxOccurs=&quot;unbounded&quot;&gt;</code> mit referenzierten Elementgruppen <code>&lt;xsd:group ref=&quot;AR:B1&quot;/&gt;</code> und <code>&lt;xsd:group ref=&quot;AR:B2&quot;/&gt;</code>.\n</li><li><code>&lt;xsd:choice minOccurs=&quot;0&quot; maxOccurs=&quot;1&quot;&gt;</code> mit referenzierter Elementgruppe <code>&lt;xsd:group ref=&quot;AR:C&quot;/&gt;</code>.\n</li></ol>\n</li><li><strong>XML instance example</strong>: Zeigt ein umschließendes Wurzelelement <code>&lt;...&gt; &lt;/...&gt;</code> mit konkreten Instanzelementen:\n<ul class=\"fig-list\"><li><code>&lt;ATT-B1&gt;someValueB1&lt;/ATT-B1&gt;</code>\n</li><li><code>&lt;ATT-B2&gt;someValueB2&lt;/ATT-B2&gt;</code>\n</li><li><code>&lt;ATT-C&gt;someValueC&lt;/ATT-C&gt;</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Entitäten entsprechen den XML-Knoten und Typgruppierungen für aggregationsfreie bzw. attributive Persistenzstrukturen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keinen zeitlichen Sequenzablauf ab, sondern ein statisches Mapping- und Validierungsverhältnis:</p>\n<ol class=\"fig-list\"><li>Im Schema erlaubt die erste Choice-Gruppe das mehrfache, beliebige Auftreten von Instanzen der Gruppen <code>AR:B1</code> und <code>AR:B2</code> (Kardinalität <code>0..*</code>).\n</li><li>Die zweite Choice-Gruppe gestattet maximal ein Vorkommen der Gruppe <code>AR:C</code> (Kardinalität <code>0..1</code>).\n</li><li>Die XML-Instanz serialisiert sequenziell Werte für <code>ATT-B1</code>, gefolgt von <code>ATT-B2</code> und <code>ATT-C</code> unter Einhaltung der Schema-Regeln.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Referenzbeispiel für Schema-Generatoren und ARXML-Serialisierer:</p>\n<ul class=\"fig-list\"><li>Schema-Erzeugung muss aggregationsfreie Referenzen bzw. Wahlmöglichkeiten strukturell über <code>xsd:choice</code> mit den definierten Kardinalitäten (<code>minOccurs</code>, <code>maxOccurs</code>) abbilden.\n</li><li>Parser und Validatoren müssen sicherstellen, dass Instanzelemente (<code>ATT-B1</code>, <code>ATT-B2</code>, <code>ATT-C</code>) der definierten Reihenfolge und Multiplizität der Schemagruppen entsprechen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-870f8c59390171f3", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Code- und Schema-Gegenüberstellungsdiagramm im Kontext der AUTOSAR XML-Persistenzregeln (<code>AUTOSAR_TR_XMLPersistenceRules</code>). Das Diagramm illustriert die Transformation von AUTOSAR-Modellstrukturen in W3C-XML-Schema-Definitionen (<code>xsd:choice</code>, <code>xsd:group</code>) und die entsprechende serielle Repräsentation in AUTOSAR-XML-Instanzdokumenten (ARXML).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Darstellung gliedert sich in zwei Zeilen:</p>\n<ul class=\"fig-list\"><li><strong>XML schema example</strong>: Enthält zwei aufeinanderfolgende XML-Schema-Ausdrücke:\n<ol class=\"fig-list\"><li><code>&lt;xsd:choice minOccurs=&quot;0&quot; maxOccurs=&quot;unbounded&quot;&gt;</code> mit referenzierten Elementgruppen <code>&lt;xsd:group ref=&quot;AR:B1&quot;/&gt;</code> und <code>&lt;xsd:group ref=&quot;AR:B2&quot;/&gt;</code>.\n</li><li><code>&lt;xsd:choice minOccurs=&quot;0&quot; maxOccurs=&quot;1&quot;&gt;</code> mit referenzierter Elementgruppe <code>&lt;xsd:group ref=&quot;AR:C&quot;/&gt;</code>.\n</li></ol>\n</li><li><strong>XML instance example</strong>: Zeigt ein umschließendes Wurzelelement <code>&lt;...&gt; &lt;/...&gt;</code> mit konkreten Instanzelementen:\n<ul class=\"fig-list\"><li><code>&lt;ATT-B1&gt;someValueB1&lt;/ATT-B1&gt;</code>\n</li><li><code>&lt;ATT-B2&gt;someValueB2&lt;/ATT-B2&gt;</code>\n</li><li><code>&lt;ATT-C&gt;someValueC&lt;/ATT-C&gt;</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Entitäten entsprechen den XML-Knoten und Typgruppierungen für aggregationsfreie bzw. attributive Persistenzstrukturen.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keinen zeitlichen Sequenzablauf ab, sondern ein statisches Mapping- und Validierungsverhältnis:</p>\n<ol class=\"fig-list\"><li>Im Schema erlaubt die erste Choice-Gruppe das mehrfache, beliebige Auftreten von Instanzen der Gruppen <code>AR:B1</code> und <code>AR:B2</code> (Kardinalität <code>0..*</code>).\n</li><li>Die zweite Choice-Gruppe gestattet maximal ein Vorkommen der Gruppe <code>AR:C</code> (Kardinalität <code>0..1</code>).\n</li><li>Die XML-Instanz serialisiert sequenziell Werte für <code>ATT-B1</code>, gefolgt von <code>ATT-B2</code> und <code>ATT-C</code> unter Einhaltung der Schema-Regeln.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Verbindliches Referenzbeispiel für Schema-Generatoren und ARXML-Serialisierer:</p>\n<ul class=\"fig-list\"><li>Schema-Erzeugung muss aggregationsfreie Referenzen bzw. Wahlmöglichkeiten strukturell über <code>xsd:choice</code> mit den definierten Kardinalitäten (<code>minOccurs</code>, <code>maxOccurs</code>) abbilden.\n</li><li>Parser und Validatoren müssen sicherstellen, dass Instanzelemente (<code>ATT-B1</code>, <code>ATT-B2</code>, <code>ATT-C</code>) der definierten Reihenfolge und Multiplizität der Schemagruppen entsprechen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-6e61465e0f300c90", "to": "FIG-870f8c59390171f3", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
